Channel<pre><code>{
  "id": "Channel",
  "description": "A specific communication connection between Asterisk and an Endpoint.",
  "properties": {
    "id": {
      "required": true,
      "type": "string",
      "description": "Unique identifier of the channel.\n\nThis is the same as the Uniqueid field in AMI."
    },
    "protocol_id": {
      "required": true,
      "type": "string",
      "description": "Protocol id from underlying channel driver (i.e. Call-ID for chan_sip/chan_pjsip; will be empty if not applicable or not implemented by driver)."
    },
    "name": {
      "required": true,
      "type": "string",
      "description": "Name of the channel (i.e. SIP/foo-0000a7e3)"
    },
    "state": {
      "required": true,
      "type": "string",
      "allowableValues": {
        "valueType": "LIST",
        "values": [
          "Down",
          "Rsrved",
          "OffHook",
          "Dialing",
          "Ring",
          "Ringing",
          "Up",
          "Busy",
          "Dialing Offhook",
          "Pre-ring",
          "Unknown"
        ]
      }
    },
    "caller": {
      "required": true,
      "type": "CallerID"
    },
    "connected": {
      "required": true,
      "type": "CallerID"
    },
    "accountcode": {
      "required": true,
      "type": "string"
    },
    "dialplan": {
      "required": true,
      "type": "DialplanCEP",
      "description": "Current location in the dialplan"
    },
    "creationtime": {
      "required": true,
      "type": "Date",
      "description": "Timestamp when channel was created"
    },
    "language": {
      "required": true,
      "type": "string",
      "description": "The default spoken language"
    },
    "channelvars": {
      "required": false,
      "type": "object",
      "description": "Channel variables"
    },
    "caller_rdnis": {
      "type": "string",
      "description": "The Caller ID RDNIS"
    },
    "tenantid": {
      "required": false,
      "type": "string",
      "description": "The Tenant ID for the channel"
    }
  }
}
</code></pre>

