ApplicationMoveFailed<pre><code>{
  "id": "ApplicationMoveFailed",
  "description": "Notification that trying to move a channel to another Stasis application failed.",
  "properties": {
    "channel": {
      "required": true,
      "type": "Channel"
    },
    "destination": {
      "required": true,
      "type": "string"
    },
    "args": {
